SELECT ID AS id, SETTLEMENT_NO AS settlement_no, supplier_no AS supplier_no, supplier_name AS supplier_name, INVOICE_TOTAL_AMOUNT AS invoice_total_amount, STATUS AS status, CREATE_TIME AS create_time FROM tb_settlement_order WHERE IS_DELETED = 0
AND supplier_no = #{supplierNo}
AND SETTLEMENT_NO LIKE CONCAT('%', #{settlementNo}, '%')
AND STATUS = #{status}
ORDER BY CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

